referenceSolutions.javascript:
export function canAttendMeetings(intervals            )          {
  const sorted = intervals.map(pair => [...pair]).sort((a,b) => a[0] - b[0]); for (let i = 1; i < sorted.length; i++) if (sorted[i][0] < sorted[i-1][1]) return false; return true;
}

